package com.bank.tgw;

import java.util.logging.*;

public class TgwDemo {
    private static final Logger log = Logger.getLogger("TGW");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        TransitGateway tgw = new TransitGateway("tgw-0hub");
        tgw.attach(new Attachment("prod",    "10.1.0.0/16"));
        tgw.attach(new Attachment("staging", "10.2.0.0/16"));
        tgw.attach(new Attachment("shared",  "10.3.0.0/16"));
        tgw.attach(new Attachment("onprem",  "172.16.0.0/16")); // via VPN

        // Transitive routing: prod reaches onprem through the hub, not direct peering.
        log.info(() -> "prod → 172.16.5.9: " + tgw.route("prod", "172.16.5.9"));
        log.info(() -> "staging → 10.3.1.1: " + tgw.route("staging", "10.3.1.1"));

        MeshComparator cmp = new MeshComparator();
        log.info(() -> "Peerings a full mesh of 4 VPCs needs: " + cmp.meshPeerings(4));
        log.info(() -> "Attachments with Transit Gateway:      " + cmp.hubAttachments(4));
    }
}

// ─── Would be in Attachment.java ───
class Attachment {
    final String name, cidr;
    Attachment(String name, String cidr) { this.name = name; this.cidr = cidr; }
    boolean owns(String ip) {
        String[] net = cidr.split("\\.");
        String[] addr = ip.split("\\.");
        int octets = Integer.parseInt(cidr.split("/")[1]) / 8;
        for (int i = 0; i < octets; i++) if (!net[i].equals(addr[i])) return false;
        return true;
    }
}

// ─── Would be in TransitGateway.java ───
class TransitGateway {
    final String id; private final java.util.List<Attachment> attachments = new java.util.ArrayList<>();
    TransitGateway(String id) { this.id = id; }
    void attach(Attachment a) { attachments.add(a); }
    // Transitive: find which attachment owns the destination and route to it.
    String route(String fromName, String destIp) {
        for (Attachment a : attachments)
            if (a.owns(destIp)) return "via " + id + " → attachment '" + a.name + "' (transitive)";
        return "no route for " + destIp;
    }
}

// ─── Would be in MeshComparator.java ───
class MeshComparator {
    int meshPeerings(int n) { return n * (n - 1) / 2; } // full mesh connections
    int hubAttachments(int n) { return n; }             // one per VPC
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), r.getMessage());
    }
}
